style.css:
@-moz-document domain("open.spotify.com") {
/* ========= PALETA ROXA (variáveis do Spotify) ========= */
  :root,
  .encore-dark-theme,
  .encore-dark-theme .encore-base-set,
  .encore-dark-theme .encore-bright-accent-set,
  body {
    --background-base: #150a26 !important;              /* fundo principal */
    --background-highlight: #241040 !important;         /* hover */
    --background-press: #0d0618 !important;
    --background-elevated-base: #2d1552 !important;     /* cards / menus */
    --background-elevated-highlight: #3d1f6e !important;
    --background-elevated-press: #1f0e3a !important;
    --background-tinted-base: #4a2585 !important;
    --background-tinted-highlight: #5b2fa3 !important;
    --background-tinted-press: #381c66 !important;

    --text-base: #f3eaff !important;
    --text-subdued: #b9a0e0 !important;
    --text-bright-accent: #c77dff !important;
    --text-negative: #ff7eb6 !important;

    --essential-base: #f3eaff !important;
    --essential-subdued: #9a7bcf !important;
    --essential-bright-accent: #9d4edd !important;      /* botões / destaques */
    --essential-announcement: #7b2cbf !important;

    --decorative-base: #f3eaff !important;
    --decorative-subdued: #5a189a !important;
  }

  /* Fundo geral com degradê roxo */
  body,
  .Root__top-container,
  .main-view-container,
  .Root__main-view {
    background: linear-gradient(160deg, #10061e 0%, #1c0b36 45%, #2a1250 100%) !important;
  }

  /* Barra lateral e topo */
  .Root__nav-bar,
  .Root__top-bar,
  [data-testid="top-bar"],
  nav {
    background-color: #170a2b !important;
  }

  /* Cards, playlists e blocos */
  [data-testid="card"],
  .main-card-card,
  .main-entityHeader-container {
    background-color: #2d1552 !important;
    border-radius: 10px !important;
  }
  [data-testid="card"]:hover,
  .main-card-card:hover {
    background-color: #3d1f6e !important;
  }

  /* Botões principais (play grande, seguir etc.) */
  [data-testid="play-button"],
  button[data-encore-id="buttonPrimary"] {
    background-color: #9d4edd !important;
    color: #fff !important;
  }
  button[data-encore-id="buttonPrimary"]:hover {
    background-color: #c77dff !important;
  }

  /* Barras de rolagem roxas */
  ::-webkit-scrollbar { width: 10px; }
  ::-webkit-scrollbar-track { background: #150a26; }
  ::-webkit-scrollbar-thumb { background: #5a189a; border-radius: 8px; }
  ::-webkit-scrollbar-thumb:hover { background: #9d4edd; }

  /* ========= PLAYER AZUL ========= */
  [data-testid="now-playing-bar"],
  footer,
  .Root__now-playing-bar {
    background: linear-gradient(90deg, #0a2a6b 0%, #1450c8 50%, #0a2a6b 100%) !important;
    border-top: 1px solid #3b82f6 !important;
  }

  /* Textos e ícones dentro do player */
  [data-testid="now-playing-bar"] *,
  footer * {
    --text-base: #eaf2ff !important;
    --text-subdued: #a9c8ff !important;
    --essential-base: #eaf2ff !important;
    --essential-subdued: #a9c8ff !important;
  }

  /* Botão play/pause do player */
  [data-testid="control-button-playpause"] {
    background-color: #60a5fa !important;
    color: #04143a !important;
  }
  [data-testid="control-button-playpause"]:hover {
    background-color: #93c5fd !important;
  }

  /* Barra de progresso e volume */
  [data-testid="playback-progressbar"],
  [data-testid="volume-bar"] {
    --fg-color: #ffffff !important;
    --bg-color: rgba(255,255,255,0.25) !important;
    --progress-bar-color: #60a5fa !important;
  }
  [data-testid="playback-progressbar"]:hover,
  [data-testid="volume-bar"]:hover {
    --progress-bar-color: #93c5fd !important;
  }
}
